import itertools

# Social Golfers: 24 golfers, 4 weeks, 6 groups of 4 each week
# No pair of golfers may be in the same group more than once.

# Let's try using Z3
import z3

n_golfers = 24
n_weeks = 4
n_groups = 6
group_size = 4

# Variables: group[w][g] = g
# We'll use integer variables: assign[w][p] = group of golfer p in week w
assign = [[z3.Int(f"w{w}_p{p}") for p in range(n_golfers)] for w in range(n_weeks)]

solver = z3.Solver()

# Each variable in range 0..5
for w in range(n_weeks):
    for p in range(n_golfers):
        solver.add(assign[w][p] >= 0, assign[w][p] < n_groups)

# Each group has exactly 4 golfers each week
for w in range(n_weeks):
    for g in range(n_groups):
        # Count golfers in group g: sum of (assign[w][p] == g) == 4
        solver.add(z3.PbEq([(assign[w][p] == g, 1) for p in range(n_golfers)], 4))

# No pair of golfers in same group more than once
for p1 in range(n_golfers):
    for p2 in range(p1+1, n_golfers):
        # For each pair, count how many weeks they share a group
        # (assign[w][p1] == assign[w][p2]) should be <= 1
        solver.add(z3.PbLe([(assign[w][p1] == assign[w][p2], 1) for w in range(n_weeks)], 1))

print("Solving...")
result = solver.check()
print(f"Result: {result}")

if result == z3.sat:
    model = solver.model()
    # Extract solution
    solution = []
    for w in range(n_weeks):
        for p in range(n_golfers):
            solution.append(model.evaluate(assign[w][p]).as_long())
    print("Solution:", solution)
    # Verify
    # Check group sizes
    for w in range(n_weeks):
        counts = [0]*6
        for p in range(n_golfers):
            counts[solution[w*24+p]] += 1
        assert all(c == 4 for c in counts), f"Week {w}: {counts}"
    # Check pairs
    pair_weeks = {}
    for w in range(n_weeks):
        for p1 in range(n_golfers):
            for p2 in range(p1+1, n_golfers):
                if solution[w*24+p1] == solution[w*24+p2]:
                    key = (p1,p2)
                    if key in pair_weeks:
                        print(f"ERROR: pair {key} meets in weeks {pair_weeks[key]} and {w}")
                    pair_weeks[key] = w
    print("Verification passed!")
else:
    print("UNSAT")
